async def seed_words_if_empty(db: AsyncSession) -> int:
    """为「英语」互动教材(KET/托业)各 active 课程补齐词库(按课程幂等)。

    每门课程(朗读/学习/测评/...)独立判断:该课程还没有 words 时从对应
    WORD_BANKS 全量插入。lexicon 全局 upsert(spelling 唯一),各课 words 行
    共享同一 lexeme_id —— 能力跨课程、跨教材互通。

    后端 lifespan 在 seed_courses 后调用。返回新写入的 words 条数。
    """
    banks: dict[str, list[tuple[str, list[str], str, str, str, str, int]]] = {
        "KET": KET_WORDS,
        "托业": TOEIC_WORDS,
    }

    # Step 1: 找各教材下还没有词的 active 课程
    pending: list[tuple[Course, list[tuple[str, list[str], str, str, str, str, int]]]] = []
    for textbook, words in banks.items():
        courses = (
            await db.execute(
                select(Course).where(
                    Course.subject == "英语",
                    Course.textbook == textbook,
                    Course.is_active.is_(True),
                )
            )
        ).scalars().all()
        for course in courses:
            has = await db.execute(
                select(Word.id).where(Word.course_id == course.id).limit(1)
            )
            if has.scalar_one_or_none() is None:
                pending.append((course, words))
    if not pending:
        return 0

    # Step 2: upsert lexicon(按 spelling 全局唯一)
    for words in banks.values():
        for spelling, _, meaning_cn, phonetic, _, _, _ in words:
            spelling_lower = spelling.lower()
            stmt = (
                insert(Lexicon)
                .values(
                    spelling=spelling_lower,
                    phonetic=phonetic,
                    meaning_cn=meaning_cn,
                    first_letter=spelling_lower[0],
                )
                .on_conflict_do_nothing(index_elements=["spelling"])
            )
            await db.execute(stmt)
    await db.flush()

    # Step 3: 查 lexeme_id map
    lexeme_rows = (await db.execute(select(Lexicon))).scalars().all()
    lexeme_map = {lex.spelling: lex.id for lex in lexeme_rows}

    # Step 4: 给每门空课程插 words(带共享 lexeme_id)
    total = 0
    for course, words in pending:
        db.add_all([
            Word(
                course_id=course.id,
                lexeme_id=lexeme_map.get(spelling.lower()),
                spelling=spelling,
                syllables=syllables,
                meaning_cn=meaning_cn,
                phonetic=phonetic,
                sample_sentence=sample_sentence,
                sample_sentence_translation=sample_sentence_translation,
                sort_order=sort_order,
            )
            for spelling, syllables, meaning_cn, phonetic, sample_sentence, sample_sentence_translation, sort_order in words
        ])
        total += len(words)
    await db.commit()
    return total
